	refs := []struct {
		Name     string
		CacheDir string
		Repo     string
		Ref      string
	}{
		{
			Name:     "Fetch Branch Name",
			CacheDir: cacheDir,
			Repo:     repo,
			Ref:      "main",
		},
		{
			Name:     "Fetch Branch Name Absolutely",
			CacheDir: cacheDir,
			Repo:     repo,
			Ref:      "refs/heads/main",
		},
		{
			Name:     "Fetch HEAD",
			CacheDir: cacheDir,
			Repo:     repo,
			Ref:      "HEAD",
		},
		{
			Name:     "Fetch Sha",
			CacheDir: cacheDir,
			Repo:     repo,
			Ref:      "de984ca37e4df4cb9fd9256435a3b82c4a2662b1",
		},
		{
			Name:     "Fetch Branch Name no existing",
			CacheDir: cacheDir,
			Repo:     repoExist,
			Ref:      "main2",
		},
		{
			Name:     "Fetch Branch Name Absolutely no existing",
			CacheDir: cacheDir,
			Repo:     repoExist,
			Ref:      "refs/heads/main2",
		},
		{
			Name:     "Fetch Sha no existing",
			CacheDir: cacheDir,
			Repo:     repoExist,
			Ref:      "de984ca37e4df4cb9fd9256435a3b82c4a2662b2",
		},
	}
	for _, c := range refs {
		t.Run(c.Name, func(t *testing.T) {
			_, err := cache.Fetch(ctx, c.CacheDir, c.Repo, c.Ref, "")
			t.Logf("%s\n", err)
			if !a.Error(err) {
				return
			}
		})
	}
